package org.example;

/**
 * Exercício 3: Tipos Primitivos e Variáveis
 * Programa que armazena e exibe dados de um produto
 */
public class Ex3 {
    public static void main(String[] args) {
        // Declaração e inicialização das variáveis
        String nome = "Teclado";
        int codigo = 12345;
        double preco = 99.90;
        boolean promocao = true;

        // Impressão formatada das informações
        System.out.println("Produto: " + nome);
        System.out.println("Código: " + codigo);
        System.out.printf("Preço: R$ %.2f%n", preco);
        System.out.println("Promoção: " + promocao);
    }
}

package org.example;

import java.util.Scanner;

/**
 * Exercício 4: Operadores
 * Programa que calcula desconto de 10% para compras acima de R$ 100
 */
public class Ex4 {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Digite o valor total da compra: R$ ");
        double valorCompra = scanner.nextDouble();

        double valorFinal;

        if (valorCompra > 100) {
            valorFinal = valorCompra * 0.9; // Aplica desconto de 10%
            System.out.printf("Valor final com desconto: R$ %.2f%n", valorFinal);
        } else {
            valorFinal = valorCompra;
            System.out.printf("Valor final sem desconto: R$ %.2f%n", valorFinal);
        }

        scanner.close();
    }
}

package org.example;

import java.util.Scanner;

/**
 * Exercício 5: Controle de Fluxo
 * Programa que categoriza a idade do usuário
 */
public class Ex5 {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Digite sua idade: ");
        int idade = scanner.nextInt();

        if (idade < 12) {
            System.out.println("Categoria: Infantil");
        } else if (idade >= 12 && idade <= 17) {
            System.out.println("Categoria: Adolescente");
        } else {
            System.out.println("Categoria: Adulto");
        }

        scanner.close();
    }
}

package org.example;

/**
 * Exercício 6: Arrays
 * Programa que registra notas de 5 alunos e calcula a média
 */
public class Ex6 {
    public static void main(String[] args) {
        // Array com as notas dos 5 alunos
        double[] notas = {7.0, 8.0, 6.0, 9.0, 10.0};

        // Imprime a lista de notas
        System.out.print("Notas: ");
        for (int i = 0; i < notas.length; i++) {
            System.out.print((int)notas[i]);
            if (i < notas.length - 1) {
                System.out.print(" ");
            }
        }
        System.out.println(); // Nova linha

        // Calcula a média
        double soma = 0;
        for (double nota : notas) {
            soma += nota;
        }
        double media = soma / notas.length;

        // Imprime a média
        System.out.printf("Média: %.1f%n", media);
    }
}
